const ALLOWED_FIELDS = ['mode','runtime_location','terminal_code','package_structural_valid','package_fingerprint_problem','approval_not_expired','write_confirmed','business_confirmed','lock_acquired','recovery_state','execution_error','authentication_success','member_command_found','get_member_found','member_exists_initial','new_member_success','assignment_success','assigned_field_count','expiry_date_assigned','member_exists_recheck','write_intent_recorded','consumed_marker_written','save_member_attempted','save_member_confirmed','save_outcome','readback_found','readback_match','masked_member_no','operation_id','source_record_id','source_fingerprint','error'];
const FORBIDDEN_FIELDS = ['member_payload','desired_business_fields','MemberNo','Name','EmailAddress','MobilePhone','DOB','member_no','name','email_address','dob','birthday','birthday_month','full_name','payload_hash','approval','password','server','database','user_id','sheet_id','sheet_url'];
const TERMINAL_CODES = ['DRY_RUN_VALIDATED','BLOCKED_MEMBER_EXISTS','APPROVAL_INVALID','SOURCE_FINGERPRINT_MISMATCH','CREATED_VERIFIED','CREATED_READBACK_MISMATCH','FAILED_BEFORE_WRITE','WRITE_OUTCOME_UNCERTAIN','OPERATOR_CONFIG_REQUIRED','WRITE_NOT_CONFIRMED','APPROVAL_REJECTED','APPROVAL_ON_HOLD','APPROVAL_ALREADY_CONSUMED','PACKAGE_ALREADY_CONSUMED','EXECUTION_LOCKED'];
const OP_RE = /^mcuat_[0-9a-f]{32}$/;
const SRID_RE = /^srcrec_[0-9a-f]{64}$/;
const FP_RE = /^fp_[0-9a-f]{64}$/;
const MASK_RE = /^(\*\*\*|.{2}\*\*\*.)$/;
const RECOVERY = ['none','terminal_exists','consumed_no_terminal','intent_no_consumed','malformed'];
const SAVE_OUTCOMES = ['not_attempted','confirmed','uncertain'];
// ExpiryDate is an active assignable field, so the runner assigns 9 whitelisted fields
// plus 2 activation fields (IsActive, Individual) = 11. Kept in sync with
// EXPECTED_ASSIGNED_FIELD_COUNT in scripts/member_create_uat_contract.py.
const EXPECTED_ASSIGNED_FIELD_COUNT = 11;

// Canonical terminal-state table (finding 4): identical to the PowerShell runner and
// the Python contract. The workflow never trusts the stored terminal_code.
function contradictions(f){
  const r=[]; const write=f.mode==='write'; const att=!!f.save_member_attempted; const conf=!!f.save_member_confirmed; const out=f.save_outcome; const rf=!!f.readback_found; const rm=!!f.readback_match;
  if(f.mode!=='dry-run'&&f.mode!=='write') r.push('mode_invalid');
  if(!RECOVERY.includes(f.recovery_state)) r.push('recovery_state_invalid');
  if(!SAVE_OUTCOMES.includes(out)) r.push('save_outcome_invalid');
  if(conf&&!att) r.push('confirmed_without_attempt');
  if(out==='confirmed'&&!conf) r.push('outcome_confirmed_without_confirmed_flag');
  if(out==='not_attempted'&&att) r.push('not_attempted_but_attempted');
  if(out==='uncertain'&&!att) r.push('uncertain_without_attempt');
  if(rm&&!rf) r.push('match_without_found');
  if((rf||rm)&&out!=='confirmed') r.push('readback_without_confirmed_save');
  if(att&&!write) r.push('attempt_in_non_write_mode');
  if(att&&!f.lock_acquired) r.push('attempt_without_lock');
  if((att||rm)&&!f.expiry_date_assigned) r.push('expiry_date_not_assigned');
  if((att||rm)&&f.assigned_field_count!==EXPECTED_ASSIGNED_FIELD_COUNT) r.push('assigned_field_count_stale');
  if(!write&&(!!f.write_confirmed||!!f.member_exists_recheck||att||conf||out!=='not_attempted')) r.push('dry_run_has_write_state');
  return r;
}
function recompute(f){
  const write=f.mode==='write'; const recovery=f.recovery_state||'none'; const out=f.save_outcome||'not_attempted';
  if(f.package_fingerprint_problem) return 'SOURCE_FINGERPRINT_MISMATCH';
  if(!f.package_structural_valid) return 'FAILED_BEFORE_WRITE';
  if(!f.approval_not_expired) return 'APPROVAL_INVALID';
  if(write&&!f.write_confirmed) return 'WRITE_NOT_CONFIRMED';
  if(write&&!f.business_confirmed) return 'OPERATOR_CONFIG_REQUIRED';
  if(!f.lock_acquired) return 'EXECUTION_LOCKED';
  if(recovery==='terminal_exists') return 'PACKAGE_ALREADY_CONSUMED';
  if(recovery==='consumed_no_terminal') return 'WRITE_OUTCOME_UNCERTAIN';
  if(recovery==='intent_no_consumed') return 'FAILED_BEFORE_WRITE';
  if(recovery==='malformed') return 'WRITE_OUTCOME_UNCERTAIN';
  if(f.execution_error) return f.save_member_attempted ? 'WRITE_OUTCOME_UNCERTAIN' : 'FAILED_BEFORE_WRITE';
  if(f.member_exists_initial) return 'BLOCKED_MEMBER_EXISTS';
  if(!write) return 'DRY_RUN_VALIDATED';
  if(f.member_exists_recheck) return 'BLOCKED_MEMBER_EXISTS';
  if(out==='uncertain') return 'WRITE_OUTCOME_UNCERTAIN';
  if(out==='not_attempted') return 'FAILED_BEFORE_WRITE';
  if(out==='confirmed'){ if(!f.readback_found) return 'WRITE_OUTCOME_UNCERTAIN'; return f.readback_match ? 'CREATED_VERIFIED' : 'CREATED_READBACK_MISMATCH'; }
  return 'FAILED_BEFORE_WRITE';
}

const items = $input.all();
if (items.length !== 1) throw new Error('create_uat_expected_one_extracted_text_item');
const text = items[0].json.data;
if (typeof text !== 'string' || !text.trim()) throw new Error('create_uat_result_empty');
let result;
try { result = JSON.parse(text); } catch (e) { throw new Error('create_uat_result_malformed_json'); }
if (!result || typeof result !== 'object' || Array.isArray(result)) throw new Error('create_uat_result_not_a_single_object');
const keys = Object.keys(result);
if (keys.some((k) => FORBIDDEN_FIELDS.includes(k))) throw new Error('create_uat_result_forbidden_field_present');
for (const req of ['terminal_code','operation_id','source_record_id','source_fingerprint']) { if (!keys.includes(req)) throw new Error('create_uat_result_required_field_missing'); }
if (keys.some((k) => !ALLOWED_FIELDS.includes(k))) throw new Error('create_uat_result_unexpected_field_present');
if (!TERMINAL_CODES.includes(result.terminal_code)) throw new Error('create_uat_terminal_code_unrecognised');
if (!OP_RE.test(result.operation_id)) throw new Error('create_uat_operation_id_invalid');
if (!SRID_RE.test(result.source_record_id)) throw new Error('create_uat_source_record_id_invalid');
if (!FP_RE.test(result.source_fingerprint)) throw new Error('create_uat_source_fingerprint_invalid');
if (result.masked_member_no !== null && result.masked_member_no !== undefined && !MASK_RE.test(String(result.masked_member_no))) throw new Error('create_uat_masked_member_no_malformed');

// Recompute-and-compare: reject contradictory flags or a stored code that does not
// match the canonical table.
const contr = contradictions(result);
if (contr.length) throw new Error('create_uat_state_contradiction');
if (recompute(result) !== result.terminal_code) throw new Error('create_uat_terminal_code_does_not_match_recomputed');

return [{ json: result }];

const OP_RE = /^mcuat_[0-9a-f]{32}$/;
const REQUIRED_EXPECTED = ['uat_create_operation_id','uat_create_source_record_id','uat_create_source_fingerprint'];
const REQUIRED_REVIEW = ['uat_create_terminal_code','uat_create_save_outcome','uat_create_reviewer_status'];
const result = $('Validate Sanitized Terminal Result Strictly').first().json;

const items = $input.all();
if (items.length !== 1) throw new Error('create_uat_requires_exactly_one_row_for_operation_id');
const row = items[0].json;
for (const c of REQUIRED_EXPECTED.concat(REQUIRED_REVIEW)) {
  if (!Object.prototype.hasOwnProperty.call(row, c)) throw new Error('create_uat_required_column_missing_add_columns_before_run');
}
const cell = (name) => String(row[name] ?? '').trim();

// operation_id is the authoritative single-use key. Reject blank / malformed /
// conflicting ids; the row's id must equal the result's id exactly.
const rowOp = cell('uat_create_operation_id');
if (!OP_RE.test(rowOp)) throw new Error('create_uat_row_operation_id_blank_or_malformed');
if (rowOp !== result.operation_id) throw new Error('create_uat_row_operation_id_conflict');

// Revalidate the stable identity and change-detection fingerprint by hash compare
// (no raw PII enters this workflow).
if (cell('uat_create_source_record_id') !== result.source_record_id) throw new Error('create_uat_source_record_id_mismatch');
if (cell('uat_create_source_fingerprint') !== result.source_fingerprint) throw new Error('create_uat_source_fingerprint_mismatch');

const wouldWrite = {
  uat_create_terminal_code: result.terminal_code,
  uat_create_save_outcome: String(result.save_outcome ?? ''),
  uat_create_reviewer_status: 'UNREVIEWED'
};
// Idempotency: blank review cells -> apply once; exact prior values -> already_applied;
// anything else is a conflicting prior mapping and is refused.
const blank = REQUIRED_REVIEW.every((c) => cell(c) === '');
const exact = REQUIRED_REVIEW.every((c) => cell(c) === String(wouldWrite[c]).trim());
let decision;
if (blank) decision = 'apply';
else if (exact) decision = 'already_applied';
else throw new Error('create_uat_conflicting_prior_mapping_refused');

return [{ json: {
  create_uat_decision: decision,
  uat_create_operation_id: rowOp,
  uat_create_terminal_code: wouldWrite.uat_create_terminal_code,
  uat_create_save_outcome: wouldWrite.uat_create_save_outcome,
  uat_create_reviewer_status: wouldWrite.uat_create_reviewer_status
} }];
